// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection, AccessorArrayLike, NumericArray } from '@stdlib/types/array';
import { Layout } from '@stdlib/types/blas';

/**
* Input array.
*/
type InputArray = NumericArray | Collection<number> | AccessorArrayLike<number>;

/**
* Output array.
*/
type OutputArray = NumericArray | Collection<number> | AccessorArrayLike<number>;

/**
* Interface describing `gcauchyMatrix`.
*/
interface Routine {
	/**
	* Generates a Cauchy matrix.
	*
	* @param order - storage layout
	* @param M - number of indexed elements in `x`
	* @param N - number of indexed elements in `y`
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param out - output array
	* @param LDO - stride length between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of `out`)
	* @returns output array
	*
	* @example
	* var x = [ 3.0, 5.0 ];
	* var y = [ 1.0, 4.0 ];
	* var out = [ 0.0, 0.0, 0.0, 0.0 ];
	*
	* gcauchyMatrix( 'row-major', x.length, y.length, x, 1, y, 1, out, 2 );
	* // out => [ 0.5, -1.0, 0.25, 1.0 ]
	*/
	<T extends OutputArray = OutputArray>( order: Layout, M: number, N: number, x: InputArray, strideX: number, y: InputArray, strideY: number, out: T, LDO: number ): T;

	/**
	* Generates a Cauchy matrix using alternative indexing semantics.
	*
	* @param M - number of indexed elements in `x`
	* @param N - number of indexed elements in `y`
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param offsetY - starting index for `y`
	* @param out - output array
	* @param strideOut1 - stride length for the first dimension of `out`
	* @param strideOut2 - stride length for the second dimension of `out`
	* @param offsetOut - starting index for `out`
	* @returns output array
	*
	* @example
	* var x = [ 3.0, 5.0 ];
	* var y = [ 1.0, 4.0 ];
	* var out = [ 0.0, 0.0, 0.0, 0.0 ];
	*
	* gcauchyMatrix.ndarray( x.length, y.length, x, 1, 0, y, 1, 0, out, 2, 1, 0 );
	* // out => [ 0.5, -1.0, 0.25, 1.0 ]
	*/
	ndarray<T extends OutputArray = OutputArray>( M: number, N: number, x: InputArray, strideX: number, offsetX: number, y: InputArray, strideY: number, offsetY: number, out: T, strideOut1: number, strideOut2: number, offsetOut: number ): T;
}

/**
* Generates a Cauchy matrix.
*
* @param order - storage layout
* @param M - number of indexed elements in `x`
* @param N - number of indexed elements in `y`
* @param x - first input array
* @param strideX - stride length for `x`
* @param y - second input array
* @param strideY - stride length for `y`
* @param out - output array
* @param LDO - stride length between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of `out`)
* @returns output array
*
* @example
* var x = [ 3.0, 5.0 ];
* var y = [ 1.0, 4.0 ];
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gcauchyMatrix( 'row-major', x.length, y.length, x, 1, y, 1, out, 2 );
* // out => [ 0.5, -1.0, 0.25, 1.0 ]
*
* @example
* var x = [ 3.0, 5.0 ];
* var y = [ 1.0, 4.0 ];
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gcauchyMatrix.ndarray( x.length, y.length, x, 1, 0, y, 1, 0, out, 2, 1, 0 );
* // out => [ 0.5, -1.0, 0.25, 1.0 ]
*/
declare var gcauchyMatrix: Routine;


// EXPORTS //

export = gcauchyMatrix;
